                        return false;
                    }
                    return true;
                }
                self.flags.handshake_state = HandshakeState.HANDSHAKE_PENDING;
                return true;
            }
            self.flags.handshake_state = HandshakeState.HANDSHAKE_COMPLETED;
            _ = self.triggerHandshakeCallback(true, self.getVerifyError());
            return true;
    }

pub fn handleEndOfRenegotiation(self: *@This()) void {
            if (((self.flags.handshake_state == HandshakeState.HANDSHAKE_RENEGOTIATION_PENDING) and ((self.ssl == null) or (BoringSSL.SSL_is_init_finished(self.ssl) != 0)))) {
                self.flags.handshake_state = HandshakeState.HANDSHAKE_COMPLETED;
                _ = self.triggerHandshakeCallback(true, self.getVerifyError());
            }
    }

pub fn handleReading(self: *@This(), buffer: *[BUFFER_SIZE]u8) bool {
            var read: usize = 0;
            _ = &read;
            while (true) {
                _ = log("handleReading", .{});
                const ssl = ((self.ssl) orelse { return false; });
                const available = buffer[read..];
                const just_read = BoringSSL.SSL_read(ssl, available.ptr, @as(c_int, @intCast(available.len)));
                _ = log("just read {d}", .{ just_read });
                if ((just_read <= 0)) {
                    const err = BoringSSL.SSL_get_error(ssl, just_read);
                    _ = BoringSSL.ERR_clear_error;
                    if (((err != BoringSSL.SSL_ERROR_WANT_READ) and (err != BoringSSL.SSL_ERROR_WANT_WRITE))) {
                        if ((err == BoringSSL.SSL_ERROR_WANT_RENEGOTIATE)) {
                            self.flags.handshake_state = HandshakeState.HANDSHAKE_RENEGOTIATION_PENDING;
                            if ((BoringSSL.SSL_renegotiate(ssl) == 0)) {
                                self.flags.handshake_state = HandshakeState.HANDSHAKE_COMPLETED;
                                _ = self.triggerHandshakeCallback(false, self.getVerifyError());
                                _ = self.triggerCloseCallback();
                                return false;
                            }
                            continue;
                        } else {
                            if ((err == BoringSSL.SSL_ERROR_ZERO_RETURN)) {
                                self.flags.received_ssl_shutdown = true;
                                _ = self.shutdown(false);
                                _ = self.handleEndOfRenegotiation();
                            }
                        }
                        self.flags.fatal_error = ((err == BoringSSL.SSL_ERROR_SSL) or (err == BoringSSL.SSL_ERROR_SYSCALL));
                        if ((read > 0)) {
                            _ = log("triggering data callback (read {d})", .{ read });
                            _ = self.triggerDataCallback(buffer[0..read]);
                            if (((self.ssl == null) or self.flags.closed_notified)) {
                                return false;
                            }
                        }
                        _ = self.triggerCloseCallback();
                        return false;
                    } else {
                        _ = log("wanna read/write just break", .{});
                        break;
                    }
                }
                _ = self.handleEndOfRenegotiation();
                read = (read + @as(usize, @intCast(just_read)));
                if ((read == buffer.len)) {
                    _ = log("triggering data callback (read {d}) and resetting read buffer", .{ read });
                    _ = self.triggerDataCallback(buffer[0..read]);
                    if (((self.ssl == null) or self.flags.closed_notified)) {
                        return false;
                    }
                    read = 0;
                }
            }
            if ((read > 0)) {
                _ = log("triggering data callback (read {d})", .{ read });
                _ = self.triggerDataCallback(buffer[0..read]);
                if (((self.ssl == null) or self.flags.closed_notified)) {
                    return false;
                }
            }
            return true;
    }

pub fn handleWriting(self: *@This(), buffer: *[BUFFER_SIZE]u8) void {
            var read: usize = 0;
            _ = &read;
            while (true) {
                const ssl = ((self.ssl) orelse { return; });
                const output = ((BoringSSL.SSL_get_wbio(ssl)) orelse { return; });
                const available = buffer[read..];
                const just_read = BoringSSL.BIO_read(output, available.ptr, @as(c_int, @intCast(available.len)));
                if ((just_read > 0)) {
                    read = (read + @as(usize, @intCast(just_read)));
                    if ((read == buffer.len)) {
                        _ = self.triggerWannaWriteCallback(buffer[0..read]);
                        read = 0;
                    }
                } else {
                    break;
                }
            }
            if ((read > 0)) {
                _ = self.triggerWannaWriteCallback(buffer[0..read]);
            }
    }

pub fn handleTraffic(self: *@This()) void {
            if (self.updateHandshakeState()) {
                var buffer: [BUFFER_SIZE]u8 = undefined;
                _ = &buffer;
                _ = self.handleWriting((&buffer));
                while ((self.hasPendingRead() and self.handleReading((&buffer)))) {
                    _ = self.handleWriting((&buffer));
                }
            }
    }
    const This = @This();
    const BUFFER_SIZE = 65536;
    pub const Flags = packed struct(u8) {
                handshake_state: HandshakeState = HandshakeState.HANDSHAKE_PENDING,
                received_ssl_shutdown: bool = false,
                sent_ssl_shutdown: bool = false,
                is_client: bool = false,
                authorized: bool = false,
                fatal_error: bool = false,
                closed_notified: bool = false,
            };
    pub const HandshakeState = enum(u2) {
                HANDSHAKE_PENDING = 0,
                HANDSHAKE_COMPLETED = 1,
                HANDSHAKE_RENEGOTIATION_PENDING = 2,
            };
    pub const Handlers = struct {
        ctx: T,
        onOpen: *const fn (T) void,
        onHandshake: *const fn (T, bool, uws.us_bun_verify_error_t) void,
        write: *const fn (T, []const u8) void,
        onData: *const fn (T, []const u8) void,
        onClose: *const fn (T) void,
    };
};
}

pub fn alwaysContinueVerify(_: c_int, _: ?*BoringSSL.X509_STORE_CTX) callconv(.c) c_int {
        return 1;
}

extern "c" fn us_get_shared_default_ca_store() callconv(.c) ?*BoringSSL.X509_STORE;
